import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 11
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter="\t",
        quotechar='"',
        strict=False,
    )

    records = []
    for record in reader:
        if record:
            records.append([value for value in record])

    if not records:
        return {"columns": [], "rows": []}

    def header_score(record: list[str]) -> tuple[int, int, int]:
        nonempty = [value.strip() for value in record if value.strip()]
        nonnumeric = sum(
            not re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)", value.replace(",", ""))
            for value in nonempty
        )
        textual = sum(bool(re.search(r"[^\W\d]", value, re.UNICODE)) for value in nonempty)
        return len(nonempty), nonnumeric, textual

    matching = [
        (header_score(record), -index, index)
        for index, record in enumerate(records)
        if len(record) == expected_width
    ]
    if matching:
        header_index = max(matching)[2]
    else:
        header_index = max(
            range(len(records)),
            key=lambda index: (len(records[index]), header_score(records[index]), -index),
        )

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    body = records[header_index + 1 :]
    width = max([len(columns)] + [len(record) for record in body])
    while len(columns) < width:
        columns.append(f"extra_{len(columns) - len(records[header_index]) + 1}")

    rows = []
    for record in body:
        rows.append(record + [""] * (width - len(record)))

    return {"columns": columns, "rows": rows}
